import unittest
from pricing.format import format_money
from pricing.money import ZERO, Money
from pricing.tax import apply_tax


class MoneyTests(unittest.TestCase):
    def test_cents_are_integers(self):
        for m in (Money(0.10), Money(0.10) * 3, Money(0.10) + Money(0.20), -Money(1.5), ZERO):
            self.assertIsInstance(m.cents, int)

    def test_repeated_addition_is_exact(self):
        total = ZERO
        for _ in range(10):
            total = total + Money(0.10)
        self.assertEqual(total, Money(1.00))
        self.assertEqual(total.cents, 100)

    def test_display_format(self):
        self.assertEqual(format_money(Money(1234.5)), "$1,234.50")
        self.assertEqual(format_money(Money(-0.05)), "-$0.05")
        self.assertEqual(format_money(ZERO), "$0.00")

    def test_tax_rounds_to_the_cent(self):
        self.assertEqual(apply_tax(Money(20.00), 0.0725), Money(21.45))


if __name__ == "__main__":
    unittest.main()
